const body = $input.first().json;
const tunnels = body.result || [];
return tunnels.map(tunnel => ({
  json: {
    tunnel_id: tunnel.id,
    tunnel_name: tunnel.name,
    status: tunnel.status,
    created_at: tunnel.created_at,
    conns_active_at: tunnel.conns_active_at,
    conns_inactive_at: tunnel.conns_inactive_at
  }
}));

const items = $input.all();
return items.map((item, index) => {
  const connections = item.json.result || [];
  const tunnelMeta = $('Extract Tunnels').all()[index]?.json || {};
  return {
    json: {
      tunnel_id: tunnelMeta.tunnel_id,
      tunnel_name: tunnelMeta.tunnel_name,
      status: tunnelMeta.status,
      created_at: tunnelMeta.created_at,
      conns_active_at: tunnelMeta.conns_active_at,
      conns_inactive_at: tunnelMeta.conns_inactive_at,
      connector_count: connections.length,
      connectors: connections.map(c => ({
        id: c.id,
        client_id: c.client_id,
        client_version: c.client_version,
        colo_name: c.colo_name,
        colo_region: c.colo_region,
        opened_at: c.opened_at,
        is_pending_reconnect: c.is_pending_reconnect,
        arch: c.arch,
        os: c.os
      }))
    }
  };
});

function parsePrometheus(text) {
    const result = {};
    if (!text || typeof text !== 'string') return result;
    const lines = text.split('\n');
    for (const line of lines) {
        const trimmed = line.trim();
        if (!trimmed || trimmed.startsWith('#')) continue;
        const match = trimmed.match(/^([a-zA-Z_:][a-zA-Z0-9_:]*)(?:\{([^}]*)\})?\s+([\d.eE+\-]+|NaN|Inf|-Inf)/);
        if (!match) continue;
        const [, name, labelStr, valueStr] = match;
        const value = parseFloat(valueStr);
        if (!result[name]) result[name] = [];
        const labels = {};
        if (labelStr) {
            const labelPairs = labelStr.match(/([a-zA-Z_][a-zA-Z0-9_]*)="([^"]*)"/g) || [];
            for (const pair of labelPairs) {
                const eqIdx = pair.indexOf('=');
                const k = pair.substring(0, eqIdx);
                const v = pair.substring(eqIdx + 1).replace(/"/g, '');
                labels[k] = v;
            }
        }
        result[name].push({ labels, value });
    }
    return result;
}

function extractNodeMetrics(metrics, nodeIp) {
    const totalReqs = (metrics['cloudflared_tunnel_total_requests'] || []).reduce((s, m) => s + m.value, 0);
    const activeStreams = (metrics['cloudflared_tunnel_active_streams'] || []).reduce((s, m) => s + m.value, 0);
    const responseCodes = {};
    (metrics['cloudflared_tunnel_response_by_code'] || []).forEach(m => {
        const code = m.labels.status_code || m.labels.code || 'unknown';
        responseCodes[code] = (responseCodes[code] || 0) + m.value;
    });
    const total2xx = Object.entries(responseCodes).filter(([k]) => k.startsWith('2')).reduce((s, [, v]) => s + v, 0);
    const totalResponses = Object.values(responseCodes).reduce((s, v) => s + v, 0);
    const successRate = totalResponses > 0 ? Math.round((total2xx / totalResponses) * 100) : null;

    // Look for connection_id OR connector_id in the Prometheus labels
    const connIds = [...new Set([
        ...(metrics['cloudflared_tunnel_total_requests'] || []).map(m => m.labels.connection_id || m.labels.connector_id).filter(Boolean),
        ...(metrics['cloudflared_tunnel_active_streams'] || []).map(m => m.labels.connection_id || m.labels.connector_id).filter(Boolean)
    ])];

    const perConnection = {};
    (metrics['cloudflared_tunnel_total_requests'] || []).forEach(m => {
        const cid = m.labels.connection_id || m.labels.connector_id;
        if (cid) perConnection[cid] = (perConnection[cid] || 0) + m.value;
    });

    return {
        node_ip: nodeIp,
        total_requests: Math.round(totalReqs),
        active_streams: Math.round(activeStreams),
        response_codes: responseCodes,
        success_rate: successRate,
        connection_ids: connIds,
        per_connection_requests: perConnection,
        raw_metric_count: Object.keys(metrics).length
    };
}

// Safely fetch previous nodes without throwing proxy errors
let node1Raw = null;
let node2Raw = null;
try { node1Raw = $('Scrape Node 1 Metrics').first()?.json || null; } catch (e) {}
try { node2Raw = $('Scrape Node 2 Metrics').first()?.json || null; } catch (e) {}

const node1Text = typeof node1Raw === 'string' ? node1Raw : (node1Raw?.data || JSON.stringify(node1Raw || {}));
const node2Text = typeof node2Raw === 'string' ? node2Raw : (node2Raw?.data || JSON.stringify(node2Raw || {}));

const node1 = extractNodeMetrics(parsePrometheus(node1Text), '192.168.30.31');
const node2 = extractNodeMetrics(parsePrometheus(node2Text), '192.168.30.32');

const totalRequests = node1.total_requests + node2.total_requests;
const node1Pct = totalRequests > 0 ? Math.round((node1.total_requests / totalRequests) * 100) : 50;
const node2Pct = totalRequests > 0 ? 100 - node1Pct : 50;

return [{
    json: {
        nodes: [
            { ...node1, load_pct: node1Pct },
            { ...node2, load_pct: node2Pct }
        ],
        total_requests: totalRequests,
        total_active_streams: node1.active_streams + node2.active_streams,
        load_balance: {
            node1_ip: '192.168.30.31',
            node1_pct: node1Pct,
            node2_ip: '192.168.30.32',
            node2_pct: node2Pct,
            is_balanced: Math.abs(node1Pct - node2Pct) <= 20
        },
        scraped_at: new Date().toISOString()
    }
}];

const Redis = require('ioredis');

const REDIS_CONFIG = {
    host: 'redis',
    port: 6379,
    db: 0,
    connectTimeout: 2000,
    maxRetriesPerRequest: 1
};

let tunnels = [];
try {
    tunnels = $('Merge Data').all().map(item => item.json);
} catch (e) {}

let metricsData = {};
try {
    metricsData = $('Parse Prometheus Metrics').first()?.json || {};
} catch (e) {
    console.error("Metrics data unavailable:", e.message);
}

const totalConnectors = tunnels.reduce((s, t) => s + (t.connector_count || 0), 0);

const enrichedTunnels = tunnels.map(tunnel => ({
    ...tunnel,
    connectors: (tunnel.connectors || []).map((connector, index) => {
        let matchingNode = (metricsData.nodes || []).find(n =>
            (n.connection_ids || []).includes(connector.client_id) ||
            (n.connection_ids || []).includes(connector.id)
        );

        // Fallback: If cloudflared doesn't expose IDs, sequentially map node metrics to connectors
        if (!matchingNode && metricsData.nodes && metricsData.nodes[index]) {
            matchingNode = metricsData.nodes[index];
        }

        return {
            ...connector,
            metrics: matchingNode ? {
                node_ip: matchingNode.node_ip,
                total_requests: matchingNode.total_requests,
                active_streams: matchingNode.active_streams,
                load_pct: matchingNode.load_pct,
                success_rate: matchingNode.success_rate,
                response_codes: matchingNode.response_codes
            } : null
        };
    })
}));

const payload = {
    summary: {
        total_tunnels: tunnels.length,
        healthy: tunnels.filter(t => t.status === 'healthy').length,
        degraded: tunnels.filter(t => t.status === 'degraded').length,
        down: tunnels.filter(t => t.status === 'inactive').length,
        total_connectors: totalConnectors,
        total_requests: metricsData.total_requests || 0,
        total_active_streams: metricsData.total_active_streams || 0
    },
    tunnels: enrichedTunnels,
    load_balance: metricsData.load_balance || null,
    nodes: metricsData.nodes || [],
    fetched_at: new Date().toISOString()
};

const redis = new Redis(REDIS_CONFIG);

return (async () => {
    try {
        await redis.set('cf:tunnel:status', JSON.stringify(payload), 'EX', 120);
        return [{ json: { success: true, cached_at: payload.fetched_at, tunnel_count: tunnels.length, connector_count: totalConnectors, total_requests: metricsData.total_requests || 0 } }];
    } catch(e) {
        return [{ json: { success: false, error: e.message } }];
    } finally {
        await redis.quit(); 
    }
})();

const Redis = require('ioredis');

const REDIS_CONFIG = {
    host: 'redis',
    port: 6379,
    db: 0,
    connectTimeout: 2000,
    maxRetriesPerRequest: 1
};

const redis = new Redis(REDIS_CONFIG);

return (async () => {
    try {
        const raw = await redis.get('cf:tunnel:status');
        if (!raw) {
            return [{ json: { error: 'No data cached yet.', fetched_at: null, summary: null, tunnels: [] } }];
        }
        return [{ json: JSON.parse(raw) }];
    } catch(e) {
        return [{ json: { error: e.message } }];
    } finally {
        await redis.quit(); 
    }
})();
